@pytest.mark.quantized_lstm_cell
@pytest.mark.parametrize("shape", LSTM_CELL_SHAPES)
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_quantized_lstm_cell(shape, dtype):
    """FlagGems quantized_lstm_cell vs the native FBGEMM op on the same data.

    The native op only accepts fp32 activations, so the quantization metadata
    (int8 weights, column offsets, scales, zero points) is dtype-independent
    and the fp32 comparison is run once per dtype entry point.
    """
    torch.manual_seed(42)
    torch.cuda.manual_seed(42)
    torch.backends.quantized.engine = "fbgemm"

    batch_size, input_size, hidden_size = shape
    device = flag_gems.device
    input = torch.randn(batch_size, input_size, dtype=torch.float32, device=device)
    h0 = torch.randn(batch_size, hidden_size, dtype=torch.float32, device=device)
    c0 = torch.randn(batch_size, hidden_size, dtype=torch.float32, device=device)
    b_ih = torch.randn(4 * hidden_size, dtype=torch.float32, device=device)
    b_hh = torch.randn(4 * hidden_size, dtype=torch.float32, device=device)

    quant = _make_cell_quantization(input_size, hidden_size)

    res_hy, res_cy = flag_gems.quantized_lstm_cell(
        *_args(input, (h0, c0), b_ih, b_hh, quant)
    )

    ref_hy, ref_cy = _aten_reference(input, h0, c0, b_ih, b_hh, quant)
    ref_hy, ref_cy = _ref_for_assert(res_hy, ref_hy), _ref_for_assert(res_cy, ref_cy)

    utils.gems_assert_close(res_hy, ref_hy, torch.float32, atol=ATOL)
    utils.gems_assert_close(res_cy, ref_cy, torch.float32, atol=ATOL)


