@pytest.mark.quantized_lstm_cell
@pytest.mark.parametrize(
    "mutate",
    [
        "h_batch",
        "c_hidden",
        "wrong_dtype_h",
        "wrong_shape_w_ih",
        "wrong_dtype_col_offsets",
        "wrong_device_h",
        "wrong_bias_size",
        "wrong_scale",
        "wrong_zp",
    ],
)
def test_quantized_lstm_cell_input_validation(mutate):
    """Malformed metadata must be rejected before launch, not silently run."""
    torch.manual_seed(0)
    torch.backends.quantized.engine = "fbgemm"
    device = flag_gems.device
    batch_size, input_size, hidden_size = 4, 8, 6
    input = torch.randn(batch_size, input_size, dtype=torch.float32, device=device)
    h0 = torch.randn(batch_size, hidden_size, dtype=torch.float32, device=device)
    c0 = torch.randn(batch_size, hidden_size, dtype=torch.float32, device=device)
    b_ih = torch.randn(4 * hidden_size, dtype=torch.float32, device=device)
    b_hh = torch.randn(4 * hidden_size, dtype=torch.float32, device=device)
    quant = list(_make_cell_quantization(input_size, hidden_size))
    scale_ih, scale_hh = quant[4], quant[5]
    zero_point_ih, zero_point_hh = quant[6], quant[7]

    h, c = h0, c0
    if mutate == "h_batch":
        h = torch.randn(batch_size + 1, hidden_size, dtype=torch.float32, device=device)
    elif mutate == "c_hidden":
        c = torch.randn(batch_size, hidden_size + 1, dtype=torch.float32, device=device)
    elif mutate == "wrong_dtype_h":
        h = h0.half()
    elif mutate == "wrong_shape_w_ih":
        quant[0] = torch.randint(
            -128, 127, (4 * hidden_size, input_size + 1), dtype=torch.int8
        ).cuda()
    elif mutate == "wrong_dtype_col_offsets":
        quant[2] = quant[2].long()
    elif mutate == "wrong_device_h":
        h = h0.cpu()
    elif mutate == "wrong_bias_size":
        b_ih = torch.randn(4 * hidden_size + 1, dtype=torch.float32, device=device)
    elif mutate == "wrong_scale":
        scale_ih = -1.0
    elif mutate == "wrong_zp":
        zero_point_ih = 999

    with pytest.raises(RuntimeError):
        flag_gems.quantized_lstm_cell(
            input,
            (h, c),
            quant[0],
            quant[1],
            b_ih,
            b_hh,
            quant[8],
            quant[9],
            quant[2],
            quant[3],
            scale_ih,
            scale_hh,
            zero_point_ih,
            zero_point_hh,
        )
